-- 20261016e: battery backfill, 709 listings, page-stated only. battery_type NOT touched.
begin;
create table if not exists public.listings_battery_backup_20261016 as
  select now() as backed_up_at, id, battery_ah, battery_chemistry, battery_voltage, battery_kwh, battery_brand, battery_source from public.listings where false;
revoke all on public.listings_battery_backup_20261016 from anon, authenticated;
create temp table g(ids bigint[], chem text, volt numeric, ah numeric, kwh numeric, brand text) on commit drop;
create temp table v on commit drop as select unnest(ids) as id, chem, volt, ah, kwh, brand from g;
  select now(), l.id, l.battery_ah, l.battery_chemistry, l.battery_voltage, l.battery_kwh, l.battery_brand, l.battery_source
  from public.listings l join v using (id);
update public.listings l set battery_chemistry=coalesce(v.chem,l.battery_chemistry), battery_voltage=coalesce(v.volt,l.battery_voltage),
  battery_ah=coalesce(v.ah,l.battery_ah), battery_kwh=coalesce(v.kwh,l.battery_kwh), battery_brand=coalesce(v.brand,l.battery_brand),
  battery_source='listing_page'
from v where v.id=l.id;
select count(*) as backfilled from public.listings where battery_source='listing_page';  -- expect 709
commit;
